import * as T from 'three';
import {inside,distance} from './world-geometry.js';
export function createUnderstory(scene,data,sources,blocked){
 let seed=70422;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;},positions=[];
 for(const f of data.features.filter(f=>f.properties.layer==='vegetation'&&f.geometry.type==='Polygon')){const r=f.geometry.coordinates[0],xs=r.map(p=>p[0]),zs=r.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minZ=Math.min(...zs),maxZ=Math.max(...zs),n=Math.min(65,Math.floor((maxX-minX)*(maxZ-minZ)/35));for(let i=0;i<n;i++){const x=minX+rand()*(maxX-minX),z=minZ+rand()*(maxZ-minZ);if(!inside([x,z],r)||blocked([x,z])||f.geometry.coordinates.slice(1).some(h=>inside([x,z],h)))continue;positions.push({x,z,y:.07,angle:rand()*Math.PI*2,scale:.8+rand()*1.25,type:rand()<.32?1:0});}}
 const batches=sources.map(source=>{const out=[];source.updateMatrixWorld(true);source.traverse(o=>{if(!o.isMesh)return;const g=o.geometry.clone().applyMatrix4(o.matrixWorld),mat=o.material.clone();mat.alphaTest=.32;mat.side=T.DoubleSide;mat.envMapIntensity=.65;const mesh=new T.InstancedMesh(g,mat,180);mesh.count=0;mesh.frustumCulled=false;mesh.receiveShadow=true;scene.add(mesh);out.push(mesh);});return out;}),dummy=new T.Object3D();let last=-1,high=true;
 return{setQuality:v=>high=v,update(t,camera){if(t-last<.55)return;last=t;const visible=positions.map(p=>({p,d:distance([p.x,p.z],[camera.position.x,camera.position.z])})).filter(a=>a.d<90).sort((a,b)=>a.d-b.d),counts=[0,0],limit=high?140:55;for(const{p}of visible){if(counts[p.type]>=limit)continue;dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(0,p.angle,0);dummy.scale.setScalar(p.scale);dummy.updateMatrix();for(const mesh of batches[p.type])mesh.setMatrixAt(counts[p.type],dummy.matrix);counts[p.type]++;}batches.forEach((arr,i)=>arr.forEach(m=>{m.count=counts[i];m.instanceMatrix.needsUpdate=true;}));}};
}
